/**
 * Security headers for every response the Pages Function serves.
 *
 * Cloudflare Pages applies public/_headers to static asset responses only
 * ("not applied to responses generated by Pages Functions", Pages docs), and
 * every Remix page, data request and resource route is a Functions response.
 * functions/_middleware.ts therefore sends each response through
 * withSecurityHeaders. public/_headers keeps a static copy for assets, and
 * securityHeaders.test.ts fails if the two drift apart.
 */

export const SECURITY_HEADERS: Readonly<Record<string, string>> = {
  "X-Frame-Options": "DENY",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
  "Strict-Transport-Security": "max-age=63072000; includeSubDomains; preload",
};

/**
 * Report-only for now: browsers log what the policy WOULD block and block
 * nothing. Switching this to "Content-Security-Policy" enforces it; do that
 * only after a staging sweep of every page type reports no violations.
 */
export const CSP_HEADER = "Content-Security-Policy-Report-Only";

const CONNECT_SRC = [
  "'self'",
  // Production API_URL (apps/web/wrangler.toml); the confirmation page polls it.
  "https://api.pivotparlor.com",
  // The API's workers.dev host: stored image and asset URLs point at it.
  "https://pivot-parlor-api.bmorris0565.workers.dev",
  "https://pivot-parlor-chatbot.bmorris0565.workers.dev",
  "https://api.stripe.com",
  "https://challenges.cloudflare.com",
];

/** The site's policy. `extraConnect` adds origins (a staging API) to connect-src. */
export function contentSecurityPolicy(extraConnect: readonly string[] = []): string {
  const connect = [...CONNECT_SRC];
  for (const origin of extraConnect) if (origin && !connect.includes(origin)) connect.push(origin);
  return [
    "default-src 'self'",
    "script-src 'self' 'unsafe-inline' https://js.stripe.com https://challenges.cloudflare.com",
    "style-src 'self' 'unsafe-inline'",
    // blob: for the staff photo preview (URL.createObjectURL).
    "img-src 'self' data: blob: https:",
    `connect-src ${connect.join(" ")}`,
    // www.google.com: the shop map embeds (google.com/maps ... output=embed).
    "frame-src https://js.stripe.com https://challenges.cloudflare.com https://www.google.com",
    "font-src 'self' data:",
    "object-src 'none'",
    "base-uri 'self'",
    // A native submit (before hydration) follows the action's redirect, and
    // Chrome checks it: the booking deposit goes to Stripe Checkout and the
    // payments setup to a Connect account link.
    "form-action 'self' https://checkout.stripe.com https://connect.stripe.com",
    "frame-ancestors 'none'",
  ].join("; ");
}

/**
 * A copy of `res` carrying the security headers. Rebuilt rather than edited in
 * place: redirects and upstream fetch() responses (the api.* proxies return
 * them as-is) have immutable headers, and setting on those throws. The body
 * stream and status carry over. A header the route already set wins, and a
 * route with its own enforced policy (dev.activity.export) gets no
 * report-only one.
 */
export function withSecurityHeaders(res: Response, opts: { apiOrigin?: string } = {}): Response {
  const out = new Response(res.body, res);
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    if (!out.headers.has(name)) out.headers.set(name, value);
  }
  if (!out.headers.has("Content-Security-Policy") && !out.headers.has(CSP_HEADER)) {
    out.headers.set(CSP_HEADER, contentSecurityPolicy(opts.apiOrigin ? [opts.apiOrigin] : []));
  }
  return out;
}
